create function pg_temp.bundle() returns jsonb language sql as $$select jsonb_set(jsonb_set(jsonb_set(pg_temp.base_bundle(),'{questions,3,student,kind}','"open_ended"'),'{questions,3,student,choices}','[]'),'{questions,3,teacher,correct_key}','null');$$;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000004301","role":"authenticated","gina":{"admin":true}}',true);
insert into state(id) select (public.admin_import_library_bundle(gen_random_uuid(),pg_temp.bundle())->>'id')::uuid;
select public.admin_review_library_question(gen_random_uuid(),(select id from state),'question-1',1,0,'suitable','Synthetic test only');
select public.admin_review_library_question(gen_random_uuid(),(select id from state),'question-2',1,0,'suitable','Synthetic test only');
select public.admin_review_library_question(gen_random_uuid(),(select id from state),'question-3',1,0,'suitable','Synthetic test only');
select public.admin_review_library_question(gen_random_uuid(),(select id from state),'question-4',1,0,'suitable','Synthetic test only');
reset role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select public.prepare_library_delivery_media('00000000-0000-4000-8000-000000004301',(select id from state),jsonb_build_array(jsonb_build_object('source_hash',pg_temp.bundle()#>>'{assets,0,sha256}','base64',pg_temp.bundle()#>>'{assets,0,base64}')));
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000004301","role":"authenticated","gina":{"admin":true}}',true);
select public.admin_set_library_publication(gen_random_uuid(),(select id from state),0,public.admin_library_publication((select id from state))#>>'{checks,review_fingerprint}','Test geometry','Test',array['free']::public.plan_code[],'Test curriculum',true,'published');


create function pg_temp.make_group() returns uuid language sql as $$select public.admin_create_reviewed_group_exam('60000000-0000-4000-8000-000000005901',(select id from state),1,'Reviewed cohort',array['source:segments','question:question-4'],now()-interval '1 hour',now()+interval '1 hour',20,array['free']::public.plan_code[],true);$$;
select lives_ok($$select pg_temp.make_group()$$,'written cohort freezes reviewed rubric');
select is(pg_temp.make_group()::text,'60000000-0000-4000-8000-000000005901','creation replay is stable');
select is(public.admin_group_package_catalog()#>>'{0,units,1,review_eligible}','true','open question eligible only for explicit review mode');
select is(public.admin_group_package_catalog()#>>'{0,units,1,eligible}','false','automatic eligibility remains false');
reset role;
insert into public.children(id,family_id,name,grade) values('20000000-0000-4000-8000-000000004702','10000000-0000-4000-8000-000000004302','Child',5);
update public.plans set cohort_monthly=5,prova_monthly_exams=null where code='free';
update public.app_settings set value='true' where key in('cohorts.enabled','sources.enabled','question_groups.enabled');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000004302","role":"authenticated","gina":{"role":"parent","family_id":"10000000-0000-4000-8000-000000004302"}}',true);
select throws_ok($$select public.enroll_group_exam('60000000-0000-4000-8000-000000005901','20000000-0000-4000-8000-000000004702',true,true)$$,'P0001','group_review_consent_required','legacy enrollment cannot silently consent to central answer review');
select set_config('test.exam',public.enroll_reviewed_group_exam('60000000-0000-4000-8000-000000005901','20000000-0000-4000-8000-000000004702',true,true,true)::text,true);
select is((select kind::text from public.question_bank where id=(select question_ids[4] from public.exams where id=current_setting('test.exam')::uuid)),'open_ended','open answer delivered without changing kind');
select is(public.get_group_exams()#>>'{groups,0,requires_review}','true','family sees review mode');
select throws_ok($$select public.admin_cohort_review_queue('60000000-0000-4000-8000-000000005901')$$,'42501','forbidden','parent cannot list cross-family review queue');
select throws_ok($$select * from gina.cohort_reviews$$,'42501',null,'central reviews private');
select set_config('test.attempt',(public.start_exam_attempt(current_setting('test.exam')::uuid)).id::text,true);
select lives_ok($$select public.submit_exam_answer(current_setting('test.attempt')::uuid,(select question_ids[1] from public.exams where id=current_setting('test.exam')::uuid),'A')$$,'MC answer still automatically scored');
select lives_ok($$select public.submit_exam_answer_v3(gen_random_uuid(),current_setting('test.attempt')::uuid,(select question_ids[4] from public.exams where id=current_setting('test.exam')::uuid),0,null,'My reasoning','{"version":1,"width":1000,"height":1400,"elements":[{"id":"70000000-0000-4000-8000-000000005901","type":"stroke","color":"#201951","size":3,"points":[[10,20],[30,40]]}]}')$$,'open notebook answer accepted in cohort');
select public.finish_exam_attempt(current_setting('test.attempt')::uuid);
select is(public.get_group_result('60000000-0000-4000-8000-000000005901','20000000-0000-4000-8000-000000004702')->>'ready','false','result hidden before group window closes');
reset role;
select set_config('test.entry',(select id::text from public.group_exam_entries where exam_id=current_setting('test.exam')::uuid),true);
select is((select count(*)::int from public.group_exam_entries where review_consent_at is not null),1,'explicit review consent recorded');
select is((select is_correct from public.exam_answers where attempt_id=current_setting('test.attempt')::uuid and answer_text='My reasoning'),null::boolean,'open answer not silently marked wrong');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000004301","role":"authenticated","gina":{"admin":true}}',true);
select throws_ok($$select public.admin_cohort_review_detail(current_setting('test.entry')::uuid)$$,'P0001','group_review_not_open','reviewer cannot see live answer');
reset role;update public.group_exams set ends_at=now()-interval '1 minute';set local role authenticated;
create function pg_temp.detail() returns jsonb language sql as $$select public.admin_cohort_review_detail(current_setting('test.entry')::uuid)$$;
create function pg_temp.review(req uuid default gen_random_uuid(),rev int default 0,pts jsonb default '{"c1":1,"c2":1,"c3":0,"c4":0}',outcome text default 'scored',ap int default null,response text default null) returns jsonb language sql as $$select public.admin_save_cohort_review(req,current_setting('test.entry')::uuid,4,rev,pg_temp.detail()#>>'{questions,3,answer_hash}',pts,outcome,'Two criteria evidenced in the answer.',ap,response)$$;
create function pg_temp.publish(req uuid default gen_random_uuid(),fingerprint text default null,version int default null) returns jsonb language sql as $$select public.admin_publish_cohort_results(req,'60000000-0000-4000-8000-000000005901',coalesce(fingerprint,public.admin_cohort_review_queue('60000000-0000-4000-8000-000000005901')#>>'{state,fingerprint}'),coalesce(version,(public.admin_cohort_review_queue('60000000-0000-4000-8000-000000005901')#>>'{state,version}')::int))$$;
select is(pg_temp.detail()#>>'{questions,3,answer_document,elements,0,type}','stroke','review includes actual child ink');
select ok(pg_temp.detail()::text not like '%family_id%' and pg_temp.detail()::text not like '%created_by%','review detail excludes family identity');
select ok(length(pg_temp.detail()#>>'{images,0,png}')>50,'frozen question media delivered for review');
select throws_ok($$select pg_temp.publish()$$,'P0001','group_review_incomplete','pending written answer blocks publication');
select throws_ok($$select pg_temp.review(pts=>'{"c1":2,"c2":1,"c3":0,"c4":0}')$$,'P0001','group_review_points','criterion maximum enforced');
select throws_ok($$select pg_temp.review(pts=>'{"c1":1,"c2":1,"c3":0}')$$,'P0001','group_review_points','missing criterion rejected');
select throws_ok($$select pg_temp.review(pts=>'{"c1":0,"c2":0,"c3":0,"c4":0}',outcome=>'not_answered')$$,'P0001','group_answer_present','ink/text cannot be called unanswered');
select throws_ok($$select public.admin_save_cohort_review(gen_random_uuid(),current_setting('test.entry')::uuid,4,0,repeat('f',64),'{"c1":1,"c2":1,"c3":0,"c4":0}','scored','Stale answer evidence.')$$,'P0001','group_review_changed','stale answer fingerprint rejected');
savepoint unreadable_case;
select lives_ok($$select pg_temp.review(pts=>'{"c1":0,"c2":0,"c3":0,"c4":0}',outcome=>'unreadable')$$,'unreadable answer can be held without a score');
select is(pg_temp.detail()#>>'{questions,3,points}',null::text,'unreadable answer is not zero');
select throws_ok($$select pg_temp.publish()$$,'P0001','group_review_incomplete','unreadable answer blocks publication');
rollback to unreadable_case;
select lives_ok($$select pg_temp.review('80000000-0000-4000-8000-000000005901')$$,'criterion review saved');
select is(pg_temp.review('80000000-0000-4000-8000-000000005901')->>'revision','1','lost review reply does not duplicate review');
select throws_ok($$select pg_temp.review()$$,'P0001','group_review_changed','stale reviewer does not overwrite');
select lives_ok($$select pg_temp.publish('80000000-0000-4000-8000-000000005902')$$,'complete cohort explicitly published');
select is(pg_temp.publish('80000000-0000-4000-8000-000000005902',version=>0)->>'version','1','lost publish reply replayed');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000004302","role":"authenticated","gina":{"role":"parent","family_id":"10000000-0000-4000-8000-000000004302"}}',true);
create function pg_temp.result() returns jsonb language sql as $$select public.get_group_result('60000000-0000-4000-8000-000000005901','20000000-0000-4000-8000-000000004702')$$;
select is(pg_temp.result()->>'points','3','one MC point plus two rubric points');
select is(pg_temp.result()->>'maximum','7','raw rubric weights fixed before participation');
select is(pg_temp.result()#>>'{ranking,0,rank}','1','published reviewed points ranked');
select is(pg_temp.result()#>>'{reviews,3,criterion_points,c1}','1','parent sees criterion evidence');
select throws_ok($$select public.admin_save_cohort_review(gen_random_uuid(),current_setting('test.entry')::uuid,4,1,'fake','{}','scored','Forged points')$$,'42501','forbidden','parent cannot change central score');
select is(public.appeal_cohort_review('80000000-0000-4000-8000-000000005903','60000000-0000-4000-8000-000000005901','20000000-0000-4000-8000-000000004702',4,1,'Please check the second explanation.')->>'status','open','parent submits private appeal');
select is(public.appeal_cohort_review('80000000-0000-4000-8000-000000005903','60000000-0000-4000-8000-000000005901','20000000-0000-4000-8000-000000004702',4,1,'Please check the second explanation.')->>'revision','1','appeal reply replayable');
select is(pg_temp.result()->>'published','false','open appeal suspends final ranking');
select is(jsonb_array_length(pg_temp.result()->'ranking'),0,'no misleading final board during appeal');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000004303","role":"authenticated","gina":{"role":"parent","family_id":"10000000-0000-4000-8000-000000004303"}}',true);
select throws_ok($$select pg_temp.result()$$,'P0001','not_found','other family cannot read reviews');
select throws_ok($$select public.appeal_cohort_review(gen_random_uuid(),'60000000-0000-4000-8000-000000005901','20000000-0000-4000-8000-000000004702',4,1,'Foreign appeal request.')$$,'42501','forbidden','other family cannot appeal');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000004301","role":"authenticated","gina":{"admin":true}}',true);
select throws_ok($$select pg_temp.publish()$$,'P0001','group_review_incomplete','open appeal blocks republication');
select throws_ok($$select pg_temp.review(rev=>1)$$,'P0001','group_appeal_response_required','reviewer must answer open appeal');
select lives_ok($$select pg_temp.review(rev=>1,pts=>'{"c1":1,"c2":1,"c3":1,"c4":0}',ap=>1,response=>'The third criterion is supported; score corrected.')$$,'appeal resolved with explicit corrected rubric');
select is(public.admin_cohort_review_queue('60000000-0000-4000-8000-000000005901')#>>'{state,published}','false','correction requires separate republication');
select lives_ok($$select pg_temp.publish()$$,'corrected results republished');
select is(jsonb_array_length(pg_temp.detail()#>'{questions,3,history}'),3,'review appeal and corrected review retained in order');
select is(pg_temp.detail()#>>'{questions,3,history,0,body,points}','2','original score retained in review history');
select is(pg_temp.detail()#>>'{questions,3,history,2,body,points}','3','corrected score retained in review history');
savepoint revoked_admin;
reset role;delete from public.admins where user_id='00000000-0000-4000-8000-000000004301';set local role authenticated;
select throws_ok($$select pg_temp.detail()$$,'42501','forbidden','revoked admin cannot read private answer');
rollback to revoked_admin;
savepoint cancelled_group;
reset role;update public.group_exams set status='cancelled' where id='60000000-0000-4000-8000-000000005901';set local role authenticated;
select throws_ok($$select pg_temp.publish()$$,'P0001','group_review_not_open','cancelled cohort cannot publish results');
rollback to cancelled_group;

select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000004302","role":"authenticated","gina":{"role":"parent","family_id":"10000000-0000-4000-8000-000000004302"}}',true);
select is(pg_temp.result()->>'points','4','corrected central score visible');
select is(pg_temp.result()#>>'{reviews,3,appeal,status}','resolved','parent sees appeal resolution');
reset role;
select lives_ok($$delete from public.families where id='10000000-0000-4000-8000-000000004302';set constraints all immediate;$$,'family deletion removes private central answer review');
select is((select count(*)::int from gina.cohort_reviews),0,'no orphan review');
select is((select count(*)::int from gina.cohort_appeals),0,'no orphan appeal');
select is((select count(*)::int from gina.cohort_review_events),0,'family deletion removes private review history');
select * from finish();rollback;
